'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',check:'M9 3H5v18h14V3h-4 M9 2h6v4H9z M8 12l2 2 5-5 M8 18h7',network:'M7 6l10 1M6 7l5 10M18 8l-5 10 M7 5a2 2 0 1 0-4 0 2 2 0 0 0 4 0 M21 7a2 2 0 1 0-4 0 2 2 0 0 0 4 0 M14 19a2 2 0 1 0-4 0 2 2 0 0 0 4 0',spark:'M12 2l2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',sliders:'M4 4v16M12 4v16M20 4v16 M1 8h6M9 16h6M17 9h6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',upload:'M12 16V3M7 8l5-5 5 5 M4 16v5h16v-5',download:'M12 3v13M7 11l5 5 5-5 M4 16v5h16v-5',search:'M20 20l-5-5 M17 10a7 7 0 1 0-14 0 7 7 0 0 0 14 0',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',close:'M6 6l12 12M18 6L6 18',folder:'M3 6h7l2 3h9v11H3z M3 6V4h7l2 2',filter:'M3 5h18M6 12h12M9 19h6',clock:'M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0 M12 7v5l3 2',external:'M14 3h7v7M21 3L10 14M10 3H3v18h18v-7',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',link:'M10 14l4-4M9 16l-2 2a4 4 0 0 1-5-5l4-4a4 4 0 0 1 5 0M15 8l2-2a4 4 0 0 1 5 5l-4 4a4 4 0 0 1-5 0',paper:'M5 2h9l5 5v15H5z M14 2v6h5M8 12h8M8 16h8',ok:'M20 12a8 8 0 1 1-4-7 M8 11l4 4L22 3',alert:'M12 3l10 18H2z M12 9v5M12 18h.01',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 0-8 0 4 4 0 0 0 8 0 M17 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',chevron:'M9 5l7 7-7 7',more:'M5 12h.01M12 12h.01M19 12h.01',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',reset:'M3 4v6h6 M4 10a8 8 0 1 1 1 8',minus:'M5 12h14',copy:'M8 8h13v13H8z M16 8V3H3v13h5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.paper}"/></svg>`;
const pages=[['overview','home','Overview'],['library','book','Study library'],['screening','check','Screening'],['analytics','list','Research analytics'],['networks','network','Bibliometrics'],['evidence','spark','Evidence studio'],['protocol','sliders','Review protocol']];
const colors=['#a996d8','#83b5a5','#d9aa8c','#91a8cf','#c797b8','#b4bc7d','#7cb7c2','#c9a779'];
const S={reviews:[],review:null,data:null,page:'overview',actor:null,queue:[],mode:'queue',selectedRecord:null,graphs:null,graphReview:null,graphType:'keywords',graphScope:'all',minimum:1,edgeMinimum:1,normalization:'cosine',selectedNode:null,camera:{x:0,y:0,z:1},evidence:null,proposal:null,evidenceFilter:'pending',librarySearch:'',sourceFilter:'all',statusFilter:'all',yearFilter:'all',sort:'newest',libraryPage:0,grid:false,job:null,analyticsData:null,analysisScope:'all',metricYear:'',metricCategory:'',venueSearch:'',venueLimit:10};
const token=$('meta[name="slr-token"]').content;
async function api(path,body){if(body?.review_id&&S.data?.review.id===body.review_id)body={...body,ledger_id:S.data.ledger_id};const res=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-SLR-Token':token,...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});const value=await res.json();if(!res.ok)throw new Error(value.error||'The request could not be completed.');return value;}
function endpoint(path,extra={}){return `/api/${path}?${new URLSearchParams({review:S.review,...extra})}`;}
function toast(message,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.innerHTML=icon(error?'alert':'ok')+`<span>${esc(message)}</span>`;$('#toasts').append(n);setTimeout(()=>n.remove(),6500);}
async function busy(button,work){const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span class="spinner" style="width:14px;height:14px"></span> Working';}try{await work();}catch(err){toast(err.message,true);}finally{if(button){button.disabled=false;button.innerHTML=old;}}}
const pct=(a,b)=>b?Math.round(a/b*100):0;
const sourceName=s=>String(s||'Unknown').replace('synthetic-','').replace('openalex','OpenAlex').replace('crossref','Crossref').replace('pubmed','PubMed');
const initials=name=>String(name||'R').split(/[\s–-]+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const pretty=k=>String(k||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
function pill(label,color=''){return `<span class="pill ${color}"><span class="dot"></span>${esc(label)}</span>`;}
function status(row){if(row.fulltext==='include')return ['Included','green'];if(row.fulltext==='exclude'||row.title==='exclude')return ['Excluded',''];if(row.title==='conflict'||row.fulltext==='conflict')return ['Conflict','red'];if(row.retrieval==='not_retrieved')return ['Not retrieved','orange'];if(row.title==='include')return ['Full-text review','purple'];return ['To screen','orange'];}
function button(label,action,kind='',symbol=''){return `<button class="button ${kind}" data-action="${action}">${symbol?icon(symbol):''}${label}</button>`;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow"><span>RESEARCH WORKSPACE</span><span class="eyebrow-dot"></span><span>${esc(new Date().toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'}))}</span></div><h1>${title}</h1><p class="page-description">${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function reviewStrip(){const d=S.data;return `<div class="review-strip"><div class="review-selector"><span class="folder-icon">${icon('folder')}</span><select class="review-select" id="review-select" aria-label="Choose review">${S.reviews.map(r=>`<option value="${r.id}" ${r.id===S.review?'selected':''}>${esc(r.name)}${r.demo?' · Demo':''}</option>`).join('')}</select></div><div class="review-meta"><div class="avatar-group">${[...d.reviewers,d.adjudicator].map((r,i)=>`<span class="avatar ${['avatar-purple','avatar-green','avatar-peach'][i]}" title="${esc(r)}">${initials(r)}</span>`).join('')}</div><span class="date-label">${d.reviewers.length+1} collaborators</span>${pill(d.retrieval.mode==='empty-review'?'Not started':d.counts.complete?'Screening complete':'Review in progress',d.counts.complete&&d.retrieval.mode!=='empty-review'?'green':'purple')}</div></div>`;}
function nav(){const d=S.data,c=d?.counts;$('#nav').innerHTML=pages.map(([id,i,title])=>`<a class="nav-item ${S.page===id?'active':''}" href="#${id}${S.review?'?review='+S.review:''}" ${S.page===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${id==='library'&&c?`<span class="nav-count">${c.records_to_screen}</span>`:id==='screening'&&c?`<span class="nav-count">${c.title_pending+c.title_conflicts+c.eligibility_pending+c.eligibility_conflicts}</span>`:id==='evidence'&&d.evidence?.pending?`<span class="nav-count">${d.evidence.pending}</span>`:''}</a>`).join('');$('#crumb').textContent=pages.find(p=>p[0]===S.page)?.[2]||'Overview';$('#demo-banner').hidden=!S.data?.review.demo;document.title=`${pages.find(p=>p[0]===S.page)?.[2]||'Workspace'} · LitAtlas`;}
function go(page){location.hash=page+(S.review?'?review='+S.review:'');$('#sidebar').classList.remove('open');}
async function boot(){try{const data=await api('/api/workspace');S.reviews=data.reviews;await route();}catch(err){$('#main').innerHTML=empty('Your workspace is unavailable',esc(err.message),'retry','Try again');}}
async function route(){$('#sidebar').classList.remove('open');const [page,query='']=location.hash.slice(1).split('?');S.page=pages.some(p=>p[0]===page)?page:'overview';const review=new URLSearchParams(query).get('review');const id=S.reviews.some(r=>r.id===review)?review:S.review||S.reviews[0]?.id;if(id!==S.review){S.data=null;$('#main').innerHTML='<div class="loading-state"><span class="spinner"></span><p>Opening review…</p></div>';S.review=id;S.analyticsData=null;S.analysisScope='all';S.metricYear='';S.metricCategory='';S.venueSearch='';S.actor=null;S.mode='queue';S.librarySearch='';S.sourceFilter='all';S.statusFilter='all';S.yearFilter='all';S.libraryPage=0;S.evidenceFilter='pending';S.selectedNode=null;S.graphs=null;S.graphReview=null;S.selectedRecord=null;S.proposal=null;S.evidence=null;S.camera={x:0,y:0,z:1};}if(!id){S.data=null;nav();$('#main').innerHTML=heading('Make room for discovery.','Your next literature review starts with a question.')+`<div class="card">${empty('A fresh workspace, a new perspective','Create a review to set your protocol, gather literature, and keep every decision connected.','new-review','Create your first review')}</div>`;return;}await refresh();}
async function refresh(){const id=S.review;const result=await api(endpoint('state'));if(id!==S.review)return;S.data=result;if(!S.actor||![...S.data.reviewers,S.data.adjudicator].includes(S.actor))S.actor=S.data.reviewers[0];nav();render();await loadPage();}
async function loadPage(){try{if(S.page==='analytics')await loadAnalytics();if(S.page==='overview'||S.page==='networks'){if(S.graphReview!==S.review||!S.graphs){await loadGraphs();}else paintGraph();}if(S.page==='screening'){await loadQueue();}if(S.page==='evidence'){const id=S.review,result=await api(endpoint('evidence'));if(id!==S.review)return;S.evidence=result;renderEvidenceContent();}}catch(err){toast(err.message,true);}}
async function loadGraphs(){const id=S.review,stamp=[S.minimum,S.edgeMinimum,S.normalization,S.graphScope].join('|');const result=await api(endpoint('networks',{minimum:S.minimum,edges:S.edgeMinimum,normalization:S.normalization,scope:S.graphScope}));if(id!==S.review||stamp!==[S.minimum,S.edgeMinimum,S.normalization,S.graphScope].join('|'))return;S.graphs=result.graphs;S.graphReview=S.review;S.graphCoverage=result.coverage;paintGraph();}
function render(){if(!S.data)return;const job=S.data.jobs?.find(j=>j.status==='running');if(job&&!pollingJobs.has(job.id))pollJob(job.id);const f={overview:renderOverview,library:renderLibrary,screening:renderScreening,networks:renderNetworks,analytics:renderAnalytics,evidence:renderEvidence,protocol:renderProtocol}[S.page];$('#main').innerHTML=`<div class="view-enter">${job?'<div class="jobs-banner"><span class="spinner"></span><span>A review job is running. Results and its session log will appear when it completes.</span></div>':''}${(S.data.jobs||[]).filter(j=>j.session_report).map(j=>`<div class="notice"><span>Pipeline session · ${esc(j.stage||'retrieval')} · ${esc(j.status)}${j.outcome==='partial'?' · source/analysis failures recorded':''}</span><button class="button small" data-action="session-report" data-job="${esc(j.id)}">Download session log</button>${j.calibration_available?`<button class="button small" data-action="calibration-sample" data-job="${esc(j.id)}">Download calibration sample</button>`:''}</div>`).join('')}${f()}</div>`;bindControls();if(S.page==='overview'||S.page==='networks')paintGraph();}
function empty(title,description,action,label,symbol='spark'){return `<div class="empty-state"><div class="empty-symbol">${icon(symbol)}</div><h2>${title}</h2><p>${description}</p>${action?button(label,action,'primary','plus'):''}</div>`;}
function bars(values){const max=Math.max(1,...values);return `<span class="mini-bars" aria-hidden="true">${values.slice(-7).map(v=>`<i style="height:${3+17*v/max}px"></i>`).join('')}</span>`;}
function metric(label,value,note,values,symbol='paper'){return `<div class="metric"><div class="metric-label">${label}<span class="metric-symbol">${icon(symbol)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom"><span>${note}</span>${bars(values)}</div></div>`;}
function workflow(){const c=S.data.counts;const steps=[['Identification',`${c.identified} records gathered`,S.data.retrieval.mode!=='empty-review','library'],['Screening',`${c.records_screened} of ${c.records_to_screen} resolved`,c.records_screened===c.records_to_screen&&c.records_to_screen>0,'screening'],['Eligibility',`${c.reports_assessed} full texts assessed`,c.complete,'screening'],['Evidence',S.data.evidence?`${S.data.evidence.covered} fields reviewed`:'Ready when screening is complete',S.data.evidence?.complete,'evidence']];return `<div class="workflow">${steps.map(([name,desc,done,page],i)=>`<button class="workflow-step" data-go="${page}"><span class="step-symbol ${done?'done':''}">${done?'✓':i+1}</span><span><strong>${name}</strong><small>${desc}</small></span><span class="workflow-arrow">›</span></button>`).join('')}</div>`;}
function renderOverview(){const d=S.data,c=d.counts,y=d.summary.publications_by_year.map(x=>x.records),ev=d.evidence;const next=d.records.filter(r=>r.title==='pending'||r.title==='conflict').slice(0,4);const stageCounts=[c.records_screened,c.records_to_screen-c.records_screened,c.reports_included];return heading('Your research, in focus.','A connected view of your literature, decisions, and the evidence taking shape.',button('Import literature','import','','upload')+button('New review','new-review','primary','plus'))+reviewStrip()+`<div class="metrics">${metric('Records gathered',c.identified,`${c.duplicates_removed} duplicates removed`,y)}${metric('Screening resolved',`${c.records_screened}<small> / ${c.records_to_screen}</small>`,`${pct(c.records_screened,c.records_to_screen)}% of your study library`,stageCounts,'check')}${metric('Reports included',c.reports_included,`${c.studies_included} distinct studies`,[c.reports_sought,c.reports_assessed,c.reports_included],'book')}${metric('Evidence reviewed',ev?`${pct(ev.covered,ev.total)}<small>%</small>`:'—',ev?`${ev.covered} of ${ev.total} fields reviewed`:'Begin after eligibility review',ev?[ev.covered,ev.total-ev.covered]:[],'spark')}</div>`+workflow()+`<div class="grid-main"><section class="card"><div class="card-head"><div><h2>Research landscape</h2><p class="card-subtitle">See the connections within your captured literature</p></div><div class="segmented"><button data-mini-type="keywords" class="${S.graphType==='keywords'?'active':''}">Keywords</button><button data-mini-type="coauthorship" class="${S.graphType==='coauthorship'?'active':''}">Authors</button></div></div><div class="landscape" id="overview-graph"><div class="loading-state" style="padding:70px 0"><span class="spinner"></span></div></div><div class="card-bottom"><div class="graph-legend" id="overview-legend"></div><button class="button ghost small" data-go="networks">Explore map ${icon('arrow')}</button></div></section><section class="card"><div class="card-head"><div><h2>Publication timeline</h2><p class="card-subtitle">When your captured research was published</p></div>${pill('By year')}</div><div class="timeline">${timeline(d.summary.publications_by_year)}<div class="timeline-labels"><strong>${d.summary.records-d.summary.missing_years}</strong> reports with known years <span style="margin-left:auto">${d.summary.missing_years} unknown</span></div></div><div class="card-bottom"><span>Counts reflect this corpus only</span><button class="button ghost small" data-go="library">View studies ${icon('arrow')}</button></div></section></div><div class="grid-main"><section class="card"><div class="card-head" style="padding-bottom:17px"><div><h2>Your next decisions</h2><p class="card-subtitle">A little progress, one paper at a time</p></div><button class="text-action" data-go="screening">Open screening ${icon('arrow')}</button></div>${next.length?studyTable(next,true):`<div class="card-body">${c.complete?'<p class="muted">Title screening is complete. Open evidence to continue your review.</p>':'<p class="muted">No title decisions remain. Continue full-text eligibility in Screening.</p>'}</div>`}<div class="card-bottom"><span>${c.title_pending} awaiting paired votes · ${c.title_conflicts+c.eligibility_conflicts} conflicts</span><span>Human decisions, always</span></div></section><section class="card"><div class="card-head"><div><h2>Review health</h2><p class="card-subtitle">The context behind your progress</p></div>${icon('more')}</div><div class="card-body"><div class="health-row">${ring(pct(c.records_screened,c.records_to_screen))}<div class="ring-label">${c.records_screened===c.records_to_screen&&c.records_to_screen?'A clear trail of decisions':'Your review is taking shape'}<small>${c.title_conflicts+c.eligibility_conflicts?`${c.title_conflicts+c.eligibility_conflicts} conflicts need a third reviewer.`:'Keep sources and paired reviewer decisions connected.'}</small></div></div>${['authors','keywords','references'].map((f,i)=>`<div class="coverage-item"><div class="coverage-label"><span>${pretty(f)} available</span><span>${d.coverage[f]} / ${c.records_to_screen}</span></div><div class="progress-track"><div class="progress-fill" style="width:${pct(d.coverage[f],c.records_to_screen)}%;background:${colors[i]}"></div></div></div>`).join('')}<div class="activity"><h3>Latest activity</h3>${d.activity.slice(0,3).map((a,i)=>`<div class="activity-row"><span class="avatar ${['avatar-purple','avatar-green','avatar-peach'][i]}">${initials(a.actor)}</span><div><p><strong>${esc(a.actor)}</strong> ${a.kind==='study'?'linked a report to a study':a.kind==='retrieval'?'updated full-text retrieval':'recorded a '+esc(a.stage)+' decision'}</p><small>${esc(a.record_id)} · ${esc(new Date(a.created_utc).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}))}</small></div></div>`).join('')||'<p class="muted" style="font-size:10px">Your first decision will appear here.</p>'}</div></div></section></div>`;}
function ring(value){return `<svg class="ring" viewBox="0 0 90 90" aria-label="${value}% screening resolved"><circle cx="45" cy="45" r="35" fill="none" stroke="var(--line)" stroke-width="6"/><circle cx="45" cy="45" r="35" fill="none" stroke="#a18acb" stroke-width="6" stroke-linecap="round" stroke-dasharray="${value*2.199} 219.9" transform="rotate(-90 45 45)"/><text x="45" y="48" text-anchor="middle" fill="var(--ink)" style="font-size:20px;font-weight:500">${value}%</text><text x="45" y="62" text-anchor="middle" fill="var(--muted)" style="font-size:7px">resolved</text></svg>`;}
function timeline(rows){if(!rows.length)return `<div class="empty-state" style="padding:45px 0"><p>No publication years yet.</p></div>`;const w=350,h=190,left=25,top=18,bottom=28,plot=h-top-bottom,max=Math.max(1,...rows.map(r=>r.records)),step=(w-left-10)/rows.length;return `<svg class="timeline-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Publications by year">${[0,.5,1].map(p=>`<line x1="${left}" x2="${w-5}" y1="${h-bottom-p*plot}" y2="${h-bottom-p*plot}" stroke="var(--line)" stroke-dasharray="3 4"/><text x="${left-8}" y="${h-bottom-p*plot+3}" text-anchor="end">${Math.round(max*p)}</text>`).join('')}${rows.map((r,i)=>`<rect class="bar" data-year="${r.year}" x="${left+i*step+step*.22}" y="${h-bottom-r.records/max*plot}" width="${step*.53}" height="${r.records/max*plot}" rx="3"><title>${r.year}: ${r.records} reports</title></rect><text x="${left+(i+.49)*step}" y="${h-7}" text-anchor="middle">${r.year}</text>`).join('')}</svg>`;}
function studyTable(rows,small=false){return `<div class="table-wrap"><table><thead><tr><th>STUDY</th><th>YEAR</th><th>${small?'STATUS':'SOURCE'}</th><th>${small?'':'DECISION'}</th></tr></thead><tbody>${rows.map(r=>{const m=r.metadata,st=status(r);return `<tr><td><button class="paper-title" data-paper="${r.record_id}"><span class="paper-dot"></span>${esc(m.title)}</button><div class="paper-meta">${esc(m.authors.slice(0,2).join(', '))}${m.authors.length>2?' et al.':''}</div></td><td>${m.year??'—'}</td><td>${small?pill(st[0],st[1]):`<span class="source-name">${esc(sourceName(m.source))}</span>`}</td><td>${small?`<button class="row-action" data-review-paper="${r.record_id}">Review ${icon('arrow')}</button>`:pill(st[0],st[1])}</td></tr>`;}).join('')}</tbody></table></div>`;}
function filteredLibrary(){let rows=S.data.records.filter(r=>{const m=r.metadata,q=S.librarySearch.toLowerCase();return (!q||[m.title,m.abstract,m.doi,...m.authors,...m.keywords].join(' ').toLowerCase().includes(q))&&(S.sourceFilter==='all'||m.source===S.sourceFilter)&&(S.yearFilter==='all'||String(m.year)===S.yearFilter)&&(S.statusFilter==='all'||status(r)[0]===S.statusFilter);});rows.sort((a,b)=>S.sort==='citations'?(b.metadata.citations??-1)-(a.metadata.citations??-1):S.sort==='title'?a.metadata.title.localeCompare(b.metadata.title):(b.metadata.year??0)-(a.metadata.year??0));return rows;}
function renderLibrary(){const rows=filteredLibrary(),limit=12,count=rows.length,start=Math.min(S.libraryPage,Math.max(0,Math.ceil(count/limit)-1))*limit,page=rows.slice(start,start+limit);return heading('A library with perspective.','Search, inspect, and organize the literature behind your review.',button('Export filtered CSV','library-export','','download')+button('Import literature','import','primary','upload'))+reviewStrip()+`<div class="toolbar"><div class="toolbar-group"><div class="search-input">${icon('search')}<input id="library-search" type="search" value="${esc(S.librarySearch)}" placeholder="Search titles, authors, keywords…" aria-label="Search studies"></div><select class="filter-select" id="source-filter" aria-label="Filter by source"><option value="all">All sources</option>${[...new Set(S.data.records.map(r=>r.metadata.source))].map(s=>`<option value="${esc(s)}" ${S.sourceFilter===s?'selected':''}>${esc(sourceName(s))}</option>`).join('')}</select><select class="filter-select" id="status-filter" aria-label="Filter by decision"><option value="all">All decisions</option>${[...new Set(S.data.records.map(r=>status(r)[0]))].map(s=>`<option ${S.statusFilter===s?'selected':''}>${s}</option>`).join('')}</select><select class="filter-select" id="year-filter" aria-label="Filter by year"><option value="all">All years</option>${[...new Set(S.data.records.map(r=>r.metadata.year).filter(Boolean))].sort().map(y=>`<option value="${y}" ${S.yearFilter===String(y)?'selected':''}>${y}</option>`).join('')}</select></div><div class="toolbar-group"><select class="filter-select" id="library-sort" aria-label="Sort studies"><option value="newest" ${S.sort==='newest'?'selected':''}>Newest first</option><option value="citations" ${S.sort==='citations'?'selected':''}>Most cited · known counts</option><option value="title" ${S.sort==='title'?'selected':''}>Title A–Z</option></select><div class="segmented"><button data-action="list-view" class="${!S.grid?'active':''}" aria-label="Table view">${icon('list')}</button><button data-action="grid-view" class="${S.grid?'active':''}" aria-label="Card view">${icon('grid')}</button></div></div></div>${!count?`<div class="card">${empty('No studies in this view','Try another search or filter, or import your first set of records.','import','Import literature','book')}</div>`:S.grid?`<div class="library-grid">${page.map(r=>`<article class="paper-card"><div style="display:flex;justify-content:space-between">${pill(sourceName(r.metadata.source))}${pill(status(r)[0],status(r)[1])}</div><button class="paper-title" data-paper="${r.record_id}">${esc(r.metadata.title)}</button><p>${esc(r.metadata.abstract.slice(0,190))}…</p><div>${r.metadata.keywords.slice(0,3).map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div><div class="paper-card-bottom"><span class="paper-meta">${r.metadata.year??'Unknown year'} · ${r.metadata.citations??'Unknown'} citations</span><button class="icon-button" data-paper="${r.record_id}" aria-label="Open study">${icon('arrow')}</button></div></article>`).join('')}</div>`:`<section class="card">${studyTable(page)}</section>`}<div class="table-footer" style="border:0;padding-inline:0"><span>${count?start+1:0}–${Math.min(start+limit,count)} of ${count} studies</span><div class="pagination"><button data-action="prev-page" ${start===0?'disabled':''} aria-label="Previous page">‹</button><button data-action="next-page" ${start+limit>=count?'disabled':''} aria-label="Next page">›</button></div></div>`;}
function renderScreening(){const d=S.data,c=d.counts;return heading('Thoughtful decisions. Clear evidence.','Read independently, record your reasoning, and keep a trace of every choice.',button('Export review','export','','download'))+reviewStrip()+`<div class="toolbar"><div class="segmented"><button data-mode="queue" class="${S.mode==='queue'?'active':''}">My screening queue</button><button data-mode="conflicts" class="${S.mode==='conflicts'?'active':''}">Conflicts · ${c.title_conflicts+c.eligibility_conflicts}</button><button data-mode="retrieval" class="${S.mode==='retrieval'?'active':''}">Retrieval · ${c.retrieval_pending}</button><button data-mode="link" class="${S.mode==='link'?'active':''}">Study links · ${c.included_reports_without_study}</button></div><div class="toolbar-group"><span class="muted" style="font-size:10px">Reviewing as</span><select id="actor-select" aria-label="Reviewer identity">${[...d.reviewers,d.adjudicator].map(a=>`<option ${S.actor===a?'selected':''}>${esc(a)}</option>`).join('')}</select></div></div><div class="notice">${icon('lock')}<span>${S.mode==='queue'?'Independent screening: this queue omits the other reviewer’s votes. Reviewer names are trusted local labels, not authenticated accounts.':S.mode==='conflicts'?'Conflicting decisions and differing exclusion reasons need the assigned third reviewer.':'Full-text retrieval and study linking are recorded explicitly; no document downloads happen automatically.'}</span></div><div id="screening-content"><div class="loading-state"><span class="spinner"></span></div></div>`;}
async function loadQueue(){const id=S.review,actor=S.actor,mode=S.mode;if(S.mode==='queue'){if(!S.data.reviewers.includes(S.actor)){S.queue=[];}else{const result=await api(endpoint('queue',{actor:S.actor}));if(id!==S.review||actor!==S.actor||mode!==S.mode)return;S.queue=result.queue;}}else{S.queue=S.data.records.filter(r=>S.mode==='conflicts'?(r.title==='conflict'||r.fulltext==='conflict'):S.mode==='retrieval'?(r.title==='include'&&r.retrieval==='pending'):(r.fulltext==='include'&&!r.study_id)).map(r=>({...r,stage:S.mode==='conflicts'?(r.title==='conflict'?'title':'fulltext'):S.mode}));}if(!S.queue.some(r=>r.record_id===S.selectedRecord))S.selectedRecord=S.queue[0]?.record_id;renderScreeningContent();}
function renderScreeningContent(){const container=$('#screening-content');if(!container)return;if(!S.queue.length){container.innerHTML=`<div class="card">${empty(S.mode==='queue'&&!S.data.reviewers.includes(S.actor)?'Choose an independent reviewer':'You’re all caught up.',S.mode==='queue'&&!S.data.reviewers.includes(S.actor)?'The adjudicator resolves conflicts. Select one of the two reviewers to open an independent queue.':'No records are waiting in this view. Switch a reviewer or stage to continue, or open the evidence studio.',S.data.counts.complete?'evidence-open':null,'Open evidence studio','ok')}</div>`;return;}const r=S.queue.find(r=>r.record_id===S.selectedRecord)||S.queue[0],m=r.metadata;const isThird=S.actor===S.data.adjudicator;container.innerHTML=`<div class="screen-layout"><section class="card queue-panel"><div class="card-head"><div><h2>${S.queue.length} ${S.queue.length===1?'paper':'papers'} in this view</h2><p class="card-subtitle">${S.mode==='queue'?esc(S.actor)+'’s independent queue':pretty(S.mode)}</p></div>${icon('list')}</div><div class="queue-list">${S.queue.map(q=>`<button class="queue-item ${q.record_id===r.record_id?'active':''}" data-queue-record="${q.record_id}"><small>${q.record_id} · ${q.metadata.year??'Unknown year'} · ${q.stage==='title'?'Title & abstract':pretty(q.stage)}</small><strong>${esc(q.metadata.title)}</strong><small>${esc(q.metadata.authors[0]||'Unknown author')}${q.metadata.authors.length>1?' et al.':''}</small></button>`).join('')}</div></section><article class="card reading-card"><div class="reading-top"><span class="section-label" style="margin:0">${r.record_id} / ${r.stage==='title'?'TITLE & ABSTRACT':pretty(r.stage).toUpperCase()}</span>${pill(sourceName(m.source),'purple')}</div><h2 class="reading-title">${esc(m.title)}</h2><p class="reading-authors">${esc(m.authors.join(', '))}<br><span class="muted">${esc(m.journal)} · ${m.year??'Unknown year'}</span></p><div class="section-label">ABSTRACT</div><p class="abstract">${esc(m.abstract||'No abstract is available in the captured metadata. Review the supplied source before deciding.')}</p><div style="margin-top:16px">${m.keywords.map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div>${r.stage==='fulltext'?`<div class="notice orange" style="margin-top:24px">${icon('paper')}<span>Assess your retrieved full text independently. The abstract above is metadata, not a replacement for the full article.</span></div>`:''}<details class="criteria-inline"><summary>Review criteria · version ${S.data.criteria.version}</summary><p style="margin-top:10px;white-space:pre-wrap">${esc(S.data.criteria.text)}</p></details><div class="decision-bar"><span class="muted" style="font-size:10px">${esc(S.actor)} · criteria v${S.data.criteria.version}</span><div class="toolbar-group">${S.mode==='retrieval'?button('Not retrieved','not-retrieved','danger')+button('Mark retrieved','retrieved','green','check'):S.mode==='link'?`<input id="study-id" placeholder="Study ID, e.g. S001" aria-label="Study ID" style="width:160px">`+`<button class="button primary" data-action="link-study" ${!isThird?'disabled':''}>Link report ${icon('link')}</button>`:S.mode==='conflicts'&&!isThird?`<span class="pill orange">Select ${esc(S.data.adjudicator)} to resolve</span>`:`<button class="button danger" data-action="exclude">Exclude ${S.mode==='queue'?'<span class="shortcut">E</span>':''}</button><button class="button green" data-action="include">Include ${S.mode==='queue'?'<span class="shortcut">I</span>':''} ${icon('arrow')}</button>`}</div></div></article></div>`;}
function renderNetworks(){return heading('Find the connections that matter.','Explore the structure of your corpus. Inspect the data behind every connection.',button('Download graph data','graph-export','','download'))+reviewStrip()+`<div class="toolbar"><div class="segmented">${[['coauthorship','Co-authorship'],['keywords','Keywords'],['cocitation','Co-citation'],['coupling','Coupling']].map(([k,n])=>`<button data-graph-type="${k}" class="${S.graphType===k?'active':''}">${n}</button>`).join('')}</div><div class="toolbar-group"><select id="graph-scope" class="filter-select" aria-label="Network corpus"><option value="all" ${S.graphScope==='all'?'selected':''}>All captured reports</option><option value="included" ${S.graphScope==='included'?'selected':''}>Included reports</option></select><select id="normalization" class="filter-select" aria-label="Edge normalization"><option value="cosine" ${S.normalization==='cosine'?'selected':''}>Cosine weights</option><option value="none" ${S.normalization==='none'?'selected':''}>Raw counts</option></select><label class="muted" style="font-size:10px">Min. occurrences <input id="min-occurrences" type="number" min="1" max="10000" value="${S.minimum}" style="width:62px;margin-left:5px" aria-label="Minimum node occurrences"></label><label class="muted" style="font-size:10px">Min. links <input id="min-edges" type="number" min="1" max="10000" value="${S.edgeMinimum}" style="width:62px;margin-left:5px" aria-label="Minimum raw edge count"></label></div></div><div class="network-layout"><section class="card"><div class="network-canvas" id="network-graph"><div class="loading-state"><span class="spinner"></span></div></div><div class="card-bottom"><div class="graph-legend" id="network-legend"></div><span>Drag to explore · scroll to zoom</span></div></section><aside class="card network-detail" id="network-detail"></aside></div><div class="notice" style="margin-top:18px">${icon('network')}<span>Full pair counting. ${S.normalization==='cosine'?'Cosine = shared incidence / √(frequency × frequency).':'Edges show raw shared counts.'} Colors show deterministic label-propagation groups. Positions are exploratory; distances do not measure similarity. Missing metadata is not evidence of absence.</span></div>`;}
function graphPositions(nodes,w,h,mini){const groups=[...new Set(nodes.map(n=>n.cluster))].sort((a,b)=>a-b),out=new Map();for(const [gi,g]of groups.entries()){const members=nodes.filter(n=>n.cluster===g),angle=gi*2*Math.PI/groups.length-.8,spread=groups.length===1?0:Math.min(w*.25,h*.24),cx=w/2+Math.cos(angle)*(groups.length===1?0:w*.27),cy=h/2+Math.sin(angle)*(groups.length===1?0:h*.24);members.forEach((n,i)=>{const a=i*2.39996+gi*.6,r=(mini?12:22)*Math.sqrt(i+.25);out.set(n.id,{x:cx+Math.cos(a)*r,y:cy+Math.sin(a)*r});});}return out;}
function paintGraph(){if(!S.graphs)return;const mini=S.page==='overview',el=mini?$('#overview-graph'):$('#network-graph');if(!el)return;const graph=S.graphs[S.graphType]||S.graphs.keywords,nodes=[...graph.nodes].sort((a,b)=>b.strength-a.strength||b.occurrences-a.occurrences||a.id.localeCompare(b.id)).slice(0,mini?42:70),ids=new Set(nodes.map(n=>n.id)),edges=graph.edges.filter(e=>ids.has(e.source)&&ids.has(e.target)),w=mini?600:850,h=mini?270:540,pos=graphPositions(nodes,w,h,mini);const max=Math.max(1,...nodes.map(n=>n.occurrences)),maxWeight=Math.max(.001,...edges.map(e=>e.weight));const graphSVG=`<svg ${!mini?'id="network-svg"':''} viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(S.graphType)} network"><g id="${mini?'mini-world':'graph-world'}">${edges.map(e=>{const a=pos.get(e.source),b=pos.get(e.target);return `<line class="graph-edge" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" style="stroke-width:${.45+(e.weight/maxWeight)*(mini?1.2:2.5)}"/>`;}).join('')}${nodes.map(n=>{const p=pos.get(n.id),radius=(mini?3:5)+(mini?5:9)*Math.sqrt(n.occurrences/max);return `<circle class="graph-node" data-node="${esc(n.id)}" cx="${p.x}" cy="${p.y}" r="${radius}" fill="${colors[(n.cluster-1)%colors.length]}" role="button" tabindex="0" aria-label="${esc(n.label)}; ${n.occurrences} occurrences"><title>${esc(n.label)} · ${n.occurrences} occurrences · ${n.degree} connections</title></circle>`;}).join('')}${nodes.filter((n,i)=>nodes.findIndex(x=>x.cluster===n.cluster)===i).slice(0,mini?5:8).map(n=>{const p=pos.get(n.id);return `<text class="graph-label" x="${p.x+10}" y="${p.y-10}">${esc(n.label.length>30?n.label.slice(0,28)+'…':n.label)}</text>`;}).join('')}</g></svg>`;if(!nodes.length){el.innerHTML=empty('No connections in this view','This corpus may not have the metadata needed for this network. Try another graph or lower the thresholds.',null,null,'network');}else if(mini){el.innerHTML=graphSVG+`<span class="network-note">${nodes.length} of ${graph.nodes.length} nodes · exploratory layout</span>`;}else{el.innerHTML=`<div class="network-corner">${pill(`${graph.nodes.length} nodes`)}${pill(`${graph.edges.length} edges`)}<span>${graph.coverage.records_with_usable_metadata}/${graph.coverage.records_total} reports with metadata</span></div>`+graphSVG+`<div class="network-controls"><button class="icon-button" data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button class="icon-button" data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><button class="icon-button" data-action="zoom-reset" aria-label="Reset network view">${icon('reset')}</button></div>`;bindGraphGestures();applyCamera();}const legend=$(mini?'#overview-legend':'#network-legend');if(legend){const groups=[...new Set(nodes.map(n=>n.cluster))].sort((a,b)=>a-b);legend.innerHTML=groups.slice(0,5).map(g=>`<span><i class="legend-dot" style="background:${colors[(g-1)%colors.length]}"></i>Group ${g}</span>`).join('')+(groups.length>5?`<span>+${groups.length-5} groups</span>`:'');}if(!mini)renderNetworkDetail();}
function renderNetworkDetail(){const el=$('#network-detail');if(!el||!S.graphs)return;const graph=S.graphs[S.graphType],node=graph.nodes.find(n=>n.id===S.selectedNode);if(!node){el.innerHTML=`<div><span class="section-label">NETWORK INSPECTOR</span><h3 style="margin-top:16px">Follow a connection.</h3><p class="detail-caption">Choose a node to inspect its occurrences, connections, and total link weight.</p>${[['Retained nodes',graph.nodes.length],['Retained edges',graph.edges.length],['Metadata coverage',`${graph.coverage.records_with_usable_metadata}/${graph.coverage.records_total}`],['Groups',graph.clustering.clusters]].map(([k,v])=>`<div class="network-stat"><span>${k}</span><span>${v}</span></div>`).join('')}</div><p class="detail-caption">The map displays up to 70 high-strength nodes. Downloaded data includes every retained node and edge.</p>`;return;}const edges=graph.edges.filter(e=>e.source===node.id||e.target===node.id).sort((a,b)=>b.weight-a.weight);el.innerHTML=`<div><span class="section-label">SELECTED ${S.graphType==='coupling'?'REPORT':'NODE'}</span><h3 style="margin-top:15px">${esc(node.label)}</h3>${pill('Group '+node.cluster,'purple')}${[['Occurrences',node.occurrences],['Connections',node.degree],['Total link weight',node.strength.toFixed(3)]].map(([k,v])=>`<div class="network-stat"><span>${k}</span><span>${v}</span></div>`).join('')}</div><div><div class="section-label" style="margin-top:23px">STRONGEST CONNECTIONS</div>${edges.slice(0,8).map(e=>{const other=graph.nodes.find(n=>n.id===(e.source===node.id?e.target:e.source));return `<div class="connection"><span title="${esc(other?.label)}">${esc(other?.label)}</span><span>${e.weight.toFixed(3)}</span></div>`;}).join('')||'<p class="detail-caption">This node is isolated at the selected thresholds.</p>'}<p class="detail-caption">Weights use ${S.normalization==='cosine'?'cosine normalization':'raw shared counts'}. ${S.graphType==='coupling'?'Occurrences here mean unique usable references.':'Occurrences count reports with this metadata.'}</p></div>`;}
function applyCamera(){const g=$('#graph-world');if(g)g.setAttribute('transform',`translate(${425+S.camera.x} ${270+S.camera.y}) scale(${S.camera.z}) translate(-425 -270)`);}
function bindGraphGestures(){const svg=$('#network-svg');if(!svg)return;let drag=null;svg.addEventListener('pointerdown',ev=>{if(ev.target.closest('[data-node]'))return;drag={x:ev.clientX,y:ev.clientY,ox:S.camera.x,oy:S.camera.y};svg.setPointerCapture(ev.pointerId);});svg.addEventListener('pointermove',ev=>{if(!drag)return;const scale=850/svg.getBoundingClientRect().width;S.camera.x=drag.ox+(ev.clientX-drag.x)*scale;S.camera.y=drag.oy+(ev.clientY-drag.y)*scale;applyCamera();});svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('pointercancel',()=>drag=null);svg.addEventListener('wheel',ev=>{ev.preventDefault();S.camera.z=Math.min(3.5,Math.max(.4,S.camera.z*(ev.deltaY>0?.9:1.1)));applyCamera();},{passive:false});}
function renderEvidence(){return heading('From findings to understanding.','Keep every extracted claim connected to its source and a human decision.',button('Export evidence','export','','download')+button('Add source text','add-source','primary','plus'))+reviewStrip()+`<div id="evidence-content"><div class="loading-state"><span class="spinner"></span></div></div>`;}
function renderEvidenceContent(){const root=$('#evidence-content');if(!root)return;const e=S.evidence;if(!e){root.innerHTML=`<div class="card">${empty('A source for every claim.',S.data.counts.complete&&S.data.counts.reports_included?'Your screening is complete. Start an evidence ledger with a saved extraction and appraisal framework.':'Finish paired screening, full-text eligibility, and study linking before starting evidence extraction.',S.data.counts.complete&&S.data.counts.reports_included?'init-evidence':null,'Start evidence review','spark')}</div>`;return;}const approved=e.proposals.filter(p=>p.state==='approve'&&!p.checks.flags.length).length,rows=e.proposals.filter(p=>S.evidenceFilter==='all'||S.evidenceFilter==='flagged'?S.evidenceFilter==='all'||p.checks.flags.length&&p.state!=='reject':p.state===S.evidenceFilter);if(!rows.some(p=>p.id===S.proposal))S.proposal=rows[0]?.id;root.innerHTML=`${!e.scope_current?`<div class="notice orange">${icon('alert')}<span>This ledger belongs to a previous or unavailable screening snapshot. History remains readable; new writes are blocked.</span></div>`:''}<div class="metrics">${metric('Approved items',approved,'Human-reviewed, unflagged items',[approved,e.proposals.length-approved],'ok')}${metric('Awaiting review',e.pending,'Proposals are never auto-approved',[e.pending,e.proposals.length-e.pending],'clock')}${metric('Grounding flags',e.flagged,'Check source and request references',[e.flagged,e.proposals.length-e.flagged],'alert')}${metric('Field coverage',`${pct(e.coverage.filter(r=>r.proposal_id!==null).length,e.coverage.length)}<small>%</small>`,`${e.coverage.length} configured fields & domains`,[e.coverage.filter(r=>r.proposal_id!==null).length,e.coverage.filter(r=>r.proposal_id===null).length],'book')}</div><div class="toolbar"><div class="segmented">${[['pending','Needs review'],['approve','Approved'],['flagged','Flagged'],['all','All items']].map(([k,n])=>`<button data-evidence-filter="${k}" class="${S.evidenceFilter===k?'active':''}">${n}</button>`).join('')}</div><div class="toolbar-group">${button('Import model response','import-ai','small','upload')}${button('Prepare AI request','prepare-ai','small','spark')}${button('Add extraction','propose','small soft','plus')}</div></div>${rows.length?`<div class="evidence-layout"><section class="card"><div class="card-head" style="padding-bottom:15px"><div><h2>${rows.length} evidence items</h2><p class="card-subtitle">${esc(e.framework.id)} · criteria v${e.scope.snapshot.criteria_version}</p></div>${icon('paper')}</div><div class="proposal-list">${rows.map(p=>`<button class="proposal-item ${p.id===S.proposal?'active':''}" data-proposal="${p.id}"><div class="proposal-top"><span>E${p.id} · ${esc(p.record_id||'Corpus hypothesis')}</span>${pill(p.checks.flags.length&&p.state!=='reject'?'Flagged':p.state==='approve'?'Approved':p.state==='reject'?'Rejected':'Pending',p.checks.flags.length&&p.state!=='reject'?'red':p.state==='approve'?'green':'orange')}</div><h3>${pretty(p.item.key)}</h3><p>${esc(p.item.value||'Not reported in supplied sources')}</p></button>`).join('')}</div></section><article class="card evidence-inspector" id="evidence-inspector"></article></div>`:`<div class="card">${empty('A clear view.','No evidence items match this view. Add source text and an extraction, or choose another filter.','propose','Add an extraction','spark')}</div>`}<div class="detail-caption">${esc(e.framework.appraisal.description)} Exact quote matching establishes occurrence, not semantic support.</div>`;renderEvidenceInspector();}
function renderEvidenceInspector(){const el=$('#evidence-inspector'),p=S.evidence?.proposals.find(p=>p.id===S.proposal);if(!el||!p)return;const source=p.item.anchors.length?S.evidence.sources.find(s=>s.id===p.item.anchors[0].source_id):null,anchor=p.item.anchors[0];let page=source&&anchor&&source.pages[anchor.page-1];let excerpt='';if(page!==undefined){const at=page.indexOf(anchor.quote);excerpt=at>=0?esc(page.slice(0,at))+`<mark>${esc(anchor.quote)}</mark>`+esc(page.slice(at+anchor.quote.length)):esc(page);}const batch=S.evidence.batches.find(b=>b.id===p.batch_id),producer=batch?.producer;el.innerHTML=`<div class="reading-top"><span class="section-label">E${p.id} / ${p.task==='gaps'?'HYPOTHESIS':pretty(p.task).toUpperCase()}</span>${pill(p.item.status==='not_reported'?'Not reported':p.checks.flags.length?'Grounding needs review':p.item.anchors.length?'Quote located':'Evidence-linked',p.checks.flags.length?'red':'purple')}</div><h2>${pretty(p.item.key)}</h2><div class="claim-value">${esc(p.item.value||'This information was not reported in the supplied sources. This does not prove it is absent from the full article.')}</div><div class="metadata-grid" style="margin-bottom:22px"><div class="metadata-cell"><small>Uncertainty · qualitative</small><strong>${pretty(p.item.uncertainty)}</strong></div><div class="metadata-cell"><small>Proposed by</small><strong>${esc(producer?.method==='ai'?producer.model:producer?.actor||'Manual entry')}</strong></div></div><div class="section-label">RATIONALE</div><p class="detail-caption" style="margin-top:0;margin-bottom:22px">${esc(p.item.rationale)}</p>${source?`<div class="source-top"><span>${esc(source.label)} · ${esc(source.kind)}</span><span>Supplied page ${anchor.page}</span></div><div class="source-excerpt">${excerpt}</div>`:p.item.evidence_ids.length?`<div class="notice">${icon('link')}<span>Hypothesis based on approved evidence ${p.item.evidence_ids.map(i=>'E'+i).join(', ')}. Independently validate before treating this as a research gap.</span></div>`:`<div class="notice orange">${icon('paper')}<span>No supporting passage is claimed for this unreported field. Check the coverage of supplied sources before approving absence.</span></div>`}${p.checks.flags.length?`<div class="notice orange">${icon('alert')}<span>${p.checks.flags.map(f=>esc(pretty(f))).join('<br>')}. Unsupported proposals cannot be approved; reject or submit a corrected item.</span></div>`:''}${p.item.anchors.length>1?`<p class="detail-caption">${p.item.anchors.length} source anchors are saved for this item. Inspect all anchors in the downloaded evidence history before approving.</p>`:''}<form id="evidence-review-form" class="review-form"><label class="field-label" for="evidence-actor">Reviewing as</label><select id="evidence-actor" name="actor" style="width:100%;margin-bottom:14px">${S.evidence.scope.actors.map(a=>`<option ${a===(producer?.method==='manual'&&S.actor===producer.actor?S.evidence.scope.actors.find(x=>x!==producer.actor):S.actor)?'selected':''}>${esc(a)}</option>`).join('')}</select><label class="field-label" for="review-rationale">Your review rationale</label><textarea id="review-rationale" placeholder="What did you check? Explain support, context, or your reason for rejection." required></textarea><label class="check-label"><input type="checkbox" id="support-confirmed"><span>I checked the source context, interpretation, uncertainty and any claim of unreported information. Manual proposals need a reviewer other than their author.</span></label><div style="display:flex;justify-content:space-between;align-items:center"><span class="muted" style="font-size:9px">Review revision ${p.revision}</span><div class="toolbar-group"><button type="button" class="button danger" data-action="reject-evidence" ${!S.evidence.scope_current?'disabled':''}>${p.state==='approve'?'Revoke approval':'Reject'}</button>${p.state!=='approve'?`<button type="button" class="button green" data-action="approve-evidence" ${p.checks.flags.length||!S.evidence.scope_current?'disabled':''}>Approve ${icon('ok')}</button>`:''}</div></div></form>${p.reviews.length?`<div class="activity"><h3>Review history</h3>${p.reviews.map(r=>`<div class="activity-row"><span class="avatar avatar-purple">${initials(r.actor)}</span><div><p>${esc(r.actor)} · ${r.decision==='approve'?'Approved':'Rejected'}</p><small>${esc(r.rationale)}</small></div></div>`).join('')}</div>`:''}`;}
function renderProtocol(){const d=S.data;return heading('A shared direction for your review.','Keep the research question, criteria, and reviewer responsibilities in one place.',button('Export review','export','','download'))+reviewStrip()+`<div class="protocol-columns"><section class="card"><div class="card-head"><div><h2>Research question & criteria</h2><p class="card-subtitle">Changes create a new screening pass and preserve the earlier history.</p></div>${pill('Version '+d.criteria.version,'purple')}</div><div class="card-body"><div class="section-label">RESEARCH QUESTION</div><p style="font-size:14px;color:var(--ink);margin-bottom:24px">${esc(d.review.question)}</p><div class="section-label">SCREENING CRITERIA</div><div class="protocol-text">${esc(d.criteria.text)}</div>${button('Revise criteria','revise-criteria','soft','sliders')}</div></section><aside class="card"><div class="card-head"><h2>People & responsibilities</h2></div><div class="card-body">${[...d.reviewers,d.adjudicator].map((a,i)=>`<div class="reviewer-line"><span class="avatar ${['avatar-purple','avatar-green','avatar-peach'][i]}">${initials(a)}</span><strong style="font-weight:500">${esc(a)}</strong><small>${i===2?'Adjudicator':'Reviewer '+(i+1)}</small></div>`).join('')}<div class="notice" style="margin:18px 0 0">${icon('users')}<span>Labels coordinate a trusted local workflow. They are not separate authenticated accounts.</span></div></div></aside></div><div class="card" style="margin-top:20px"><div class="card-head"><h2>Capture & coverage</h2></div><div class="card-body"><div class="metadata-grid"><div class="metadata-cell"><small>Input mode</small><strong>${esc(pretty(d.retrieval.mode||'Connected ledger'))}</strong></div><div class="metadata-cell"><small>Retrieval limits</small><strong>${d.retrieval.truncated?'At least one search was capped':'Inspect source coverage and protocol'}</strong></div></div><p class="detail-caption">A completed screening pass covers the captured corpus. It does not establish an exhaustive search. Source coverage, search syntax, and citation counts differ between providers.</p></div></div>`;}
function bindControls(){for(const [id,key]of [['analysis-scope','analysisScope'],['metric-year','metricYear'],['metric-category','metricCategory']]){const el=$('#'+id);if(el)el.onchange=async()=>{S[key]=el.value;S.analyticsData=null;render();try{await loadAnalytics();}catch(err){toast(err.message,true);}};}const venueSearch=$('#venue-search');if(venueSearch)venueSearch.oninput=()=>{S.venueSearch=venueSearch.value;$('#venue-table-content').innerHTML=venueTable(S.analyticsData);};const venueLimit=$('#venue-limit');if(venueLimit)venueLimit.onchange=()=>{S.venueLimit=Number(venueLimit.value);$('#venue-table-content').innerHTML=venueTable(S.analyticsData);};const select=$('#review-select');if(select)select.onchange=()=>{S.data=null;$('#main').innerHTML='<div class="loading-state"><span class="spinner"></span></div>';S.review=null;for(const link of $$('#nav a'))link.setAttribute('href','#'+link.getAttribute('href').slice(1).split('?')[0]+'?review='+select.value);location.hash=S.page+'?review='+select.value;};const input=$('#library-search');if(input)input.oninput=()=>{const at=input.selectionStart;S.librarySearch=input.value;S.libraryPage=0;render();const n=$('#library-search');n.focus();n.setSelectionRange(at,at);};for(const [id,key]of [['source-filter','sourceFilter'],['status-filter','statusFilter'],['year-filter','yearFilter'],['library-sort','sort']]){const el=$('#'+id);if(el)el.onchange=()=>{S[key]=el.value;S.libraryPage=0;render();};}const actor=$('#actor-select');if(actor)actor.onchange=async()=>{S.actor=actor.value;S.selectedRecord=null;await loadQueue();};for(const [id,key]of [['graph-scope','graphScope'],['normalization','normalization'],['min-occurrences','minimum'],['min-edges','edgeMinimum']]){const el=$('#'+id);if(el)el.onchange=async()=>{S[key]=el.type==='number'?Number(el.value):el.value;S.graphs=null;S.camera={x:0,y:0,z:1};render();try{await loadGraphs();}catch(err){toast(err.message,true);}};}}
function showModal(title,description,content,label,submit){const modal=$('#modal'),reviewAtOpen=S.review,ledgerAtOpen=S.data?.ledger_id;modal.innerHTML=`<form id="modal-form"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body"><p class="modal-description">${description}</p>${content}<div class="form-error" id="modal-error" role="alert"></div></div><div class="modal-footer"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">${label}</button></div></form>`;modal.showModal();$('#modal-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget,button=$('button[type="submit"]',form);button.disabled=true;$('#modal-error').textContent='';try{if(reviewAtOpen&&(reviewAtOpen!==S.review||ledgerAtOpen!==S.data?.ledger_id))throw new Error('This review changed while the dialog was open. Close it and open the action again.');await submit(new FormData(form),form);modal.close();}catch(err){$('#modal-error').textContent=err.message;}finally{button.disabled=false;}};}
const field=(name,label,placeholder='',value='',type='text')=>`<div class="form-field"><label class="field-label" for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" placeholder="${esc(placeholder)}" value="${esc(value)}" required></div>`;
const area=(name,label,value='',placeholder='')=>`<div class="form-field"><label class="field-label" for="field-${name}">${label}</label><textarea id="field-${name}" name="${name}" placeholder="${esc(placeholder)}" required>${esc(value)}</textarea></div>`;
function newReview(){showModal('A new perspective starts here.','Give your review a question and a shared set of criteria. You can import literature or search connected public databases next.',field('name','Review name','e.g. AI-supported learning in higher education')+area('question','Research question','','What do you want to understand?')+area('criteria','Inclusion & exclusion criteria','','Describe the populations, study designs, outcomes and limits for this review.')+`<div class="form-row">${field('reviewer1','First reviewer','Name')}${field('reviewer2','Second reviewer','Name')}</div>`+field('adjudicator','Adjudicator','A third reviewer for conflicts'),'Create review',async data=>{const entry=await api('/api/create',{name:data.get('name'),question:data.get('question'),criteria:data.get('criteria'),reviewers:[data.get('reviewer1'),data.get('reviewer2')],adjudicator:data.get('adjudicator')});S.reviews=(await api('/api/workspace')).reviews;S.review=null;location.hash='library?review='+entry.id;toast('Review created. Your library is ready for literature.');});}
function importModal(){if(!S.review)return newReview();if(S.data.activity.length)return showModal('Keep this review’s decisions connected.','This review is already under way. Start another review to work with a different set of literature; earlier decisions will stay connected to their original papers.','','Create another review',async()=>{setTimeout(newReview,0);});showModal('Bring your literature together.','Import individual-paper metadata as CSV, RIS or normalized JSON. The source files and duplicate matches are retained. Imports are available before screening begins.',`<div class="segmented" style="margin-bottom:20px"><button type="button" class="active">Import files</button><button type="button" data-action="search-modal">Search databases</button></div><label class="dropzone">${icon('upload')}<strong>Choose literature files</strong><small>CSV, RIS or normalized JSON · up to 5 MB total</small><input type="file" name="files" accept=".csv,.ris,.json" multiple required aria-label="Literature files"></label><div style="margin-top:18px">${field('source','Source label','e.g. Scopus search · October 2026')}</div>`,'Import literature',async(data)=>{const files=data.getAll('files').filter(f=>f.size);if(files.reduce((sum,f)=>sum+f.size,0)>5*1024*1024)throw new Error('Choose files totaling 5 MB or less.');const uploads=[];for(const file of files){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.slice(i,i+8192));uploads.push({name:file.name,base64:btoa(binary)});}await api('/api/import',{review_id:S.review,source:data.get('source'),files:uploads});S.graphs=null;await refresh();toast('Literature imported and DOI duplicates checked.');});}
function searchModal(){if(!S.review)return newReview();showModal('Search the scholarly record.','Retrieve metadata from public scholarly APIs. OpenAlex may require an API key for pagination. Retrieval limits and source coverage are recorded with your review.',area('query','Search queries — one per line','','Each line runs through the retrieval pipeline. Use source-appropriate syntax.')+`<div class="form-field"><label class="field-label" for="search-sources">Databases</label><select id="search-sources" name="sources" multiple required size="3"><option value="openalex">OpenAlex</option><option value="crossref">Crossref</option><option value="pubmed">PubMed</option></select><small>Choose one or more. Query syntax differs between providers.</small></div><div class="form-row">${field('year_from','From year','2020','2020','number')}${field('year_to','Through year','2025','2025','number')}</div>`+`<div class="form-row">${field('date_from','Exact start date (optional)','','','date')}${field('date_to','Exact cutoff (optional)','','','date')}</div>`+`<div class="form-field"><label class="field-label" for="relevance-policy">Query calibration policy (optional JSON)</label><input id="relevance-policy" type="file" name="relevance_policy" accept=".json"><small>Creates term-cue diagnostics and a blank human-review sample.</small></div>`+field('limit','Maximum records per source','100','100','number'),'Start retrieval',async data=>{const job=await api('/api/search',{review_id:S.review,query:String(data.get('query')).split('\n').map(q=>q.trim()).filter(Boolean)[0],queries:String(data.get('query')).split('\n').map(q=>q.trim()).filter(Boolean),sources:data.getAll('sources'),year_from:Number(data.get('year_from')),year_to:Number(data.get('year_to')),relevance_policy:data.get('relevance_policy')?.size?JSON.parse(await data.get('relevance_policy').text()):null,date_from:data.get('date_from')||null,date_to:data.get('date_to')||null,limit:Number(data.get('limit'))});S.job=job;toast('Retrieval started. You can keep this workspace open.');pollJob(job.id);});}
const pollingJobs=new Set();
async function pollJob(id){pollingJobs.add(id);try{const job=await api('/api/job?id='+id);if(job.status==='running'){$('#footer-status').textContent=job.stage||'Literature retrieval in progress…';setTimeout(()=>pollJob(id),1700);}else{pollingJobs.delete(id);S.job=null;$('#footer-status').textContent=job.status==='complete'?'Literature retrieval complete.':'Retrieval needs attention.';if(job.status==='complete'){S.graphs=null;await refresh();toast(job.outcome==='partial'?'Pipeline finished with source failures. Inspect the session report before using this corpus.':'Pipeline finished. Captured records and the session report are ready.',job.outcome==='partial');}else{await refresh();toast(job.error||'Retrieval failed.',true);}}}catch(err){toast(err.message,true);}}
async function decide(value){const row=S.queue.find(r=>r.record_id===S.selectedRecord);if(!row)return;const action=S.mode==='conflicts'?'adjudicate':'decide';const save=async reason=>{await api('/api/screening',{review_id:S.review,action,version:S.data.criteria.version,record_id:row.record_id,actor:S.actor,stage:row.stage,decision:value,reason});S.graphs=null;await refresh();toast(value==='include'?'Inclusion decision recorded.':'Exclusion decision recorded.');};if(value==='exclude'||action==='adjudicate'){showModal(value==='exclude'?'Record an exclusion.':'Resolve this conflict.','Your reason is saved with this decision. Use consistent primary exclusion reasons from your protocol.',area('reason',value==='exclude'?'Primary exclusion reason':'Resolution rationale','','Explain the population, design, outcome or criterion that determines this decision.'),'Record decision',async data=>save(data.get('reason')));}else await save('');}
async function evidenceReview(decision,button){const p=S.evidence.proposals.find(p=>p.id===S.proposal);if(!p)return;const rationale=$('#review-rationale').value;if(!rationale.trim()){toast('Add a rationale for this review decision.',true);$('#review-rationale').focus();return;}const confirmed=$('#support-confirmed').checked;if(decision==='approve'&&!confirmed){toast('Confirm that you checked source support, context and uncertainty.',true);return;}await busy(button,async()=>{await api('/api/evidence',{review_id:S.review,action:'review',proposal_id:p.id,actor:$('#evidence-actor').value,decision,rationale,revision:p.revision,support_confirmed:confirmed});await refresh();toast(decision==='approve'?'Evidence approved with your review rationale.':'Review decision recorded. Earlier history is retained.');});}
function initEvidence(){showModal('Start a source-grounded evidence ledger.','Your completed screening snapshot and study links will be saved with this ledger. The default framework is illustrative; upload a review-specific framework when appropriate.',`<div class="notice">${icon('paper')}<span>The default includes extraction fields and appraisal domains. It does not produce a validated risk-of-bias score.</span></div><div class="form-field"><label class="field-label" for="framework-file">Custom framework (optional JSON)</label><input id="framework-file" type="file" name="framework" accept=".json"></div>`,'Start evidence review',async data=>{const file=data.get('framework');const body={review_id:S.review,action:'init'};if(file?.size)body.framework=JSON.parse(await file.text());await api('/api/evidence',body);await refresh();toast('Evidence ledger created for this screening snapshot.');});}
function sourceModal(){if(!S.evidence){toast('Start an evidence ledger after screening is complete.',true);return;}showModal('Give your evidence a source.','Paste UTF-8 text or load a text file. Form-feed separators define supplied pages; these are not automatically verified PDF pages.',`<div class="form-field"><label class="field-label">Included report</label><select name="record_id">${S.evidence.records.map(r=>`<option value="${r.id}">${esc(r.metadata.title)}</option>`).join('')}</select></div>`+field('label','Source label','e.g. Supplied article text · methods and results')+`<div class="form-field"><label class="field-label">Source kind</label><select name="kind"><option value="fulltext">Full text</option><option value="abstract">Abstract</option><option value="excerpt">Excerpt</option></select></div><div class="form-field"><label class="field-label" for="source-file">Load a text file (optional)</label><input id="source-file" type="file" accept=".txt"></div>`+area('text','Source text','','Paste the text you will use to verify extraction and appraisal.'),'Attach source',async data=>{await api('/api/evidence',{review_id:S.review,action:'source',record_id:data.get('record_id'),kind:data.get('kind'),label:data.get('label'),text:data.get('text')});await refresh();toast('Source pages and their hash are saved.');});$('#source-file').onchange=async ev=>{const f=ev.target.files[0];if(f)$('#field-text').value=await f.text();};}
function proposeModal(){if(!S.evidence)return toast('Create an evidence ledger first.',true);const e=S.evidence;showModal('Capture a finding, keep its source.','Every manual extraction is a proposal. It remains pending until a human checks and approves it.',`<div class="form-row"><div class="form-field"><label class="field-label">Task</label><select name="task" id="proposal-task"><option value="extract">Extraction</option><option value="appraise">Appraisal</option></select></div><div class="form-field"><label class="field-label">Proposing as</label><select name="actor">${e.scope.actors.map(a=>`<option>${esc(a)}</option>`).join('')}</select></div></div><div class="form-field"><label class="field-label">Included report</label><select name="record_id" id="proposal-report">${e.records.map(r=>`<option value="${r.id}">${esc(r.metadata.title)}</option>`).join('')}</select></div><div class="form-row"><div class="form-field"><label class="field-label">Field / domain</label><select name="key" id="proposal-key"></select></div><div class="form-field"><label class="field-label">Reported status</label><select name="status"><option value="reported">Reported in supplied source</option><option value="not_reported">Not reported in supplied sources</option></select></div></div><div class="form-field"><label class="field-label">Value / judgment</label><textarea name="value" id="proposal-value" placeholder="Preserve the source meaning. For appraisal, use an allowed judgment label."></textarea><small id="judgment-hint"></small></div><div class="form-row"><div class="form-field"><label class="field-label">Source</label><select name="source_id" id="proposal-source"></select></div><div class="form-field"><label class="field-label">Supplied page</label><input name="page" type="number" min="1" value="1"></div></div><div class="form-field"><label class="field-label">Exact source quote</label><textarea name="quote" placeholder="A literal passage from the selected page. Leave blank for unreported information."></textarea></div><div class="form-field"><label class="field-label">Uncertainty · qualitative</label><select name="uncertainty"><option value="unknown">Unknown</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></div>`+area('rationale','Extraction / appraisal rationale','','Explain the interpretation or the limits of the supplied information.'),'Save proposal',async data=>{const reported=data.get('status')==='reported';const item={key:data.get('key'),status:data.get('status'),value:reported?data.get('value'):null,anchors:reported&&data.get('quote')?[{source_id:Number(data.get('source_id')),page:Number(data.get('page')),quote:data.get('quote')}]:[],evidence_ids:[],uncertainty:data.get('uncertainty'),rationale:data.get('rationale')};await api('/api/evidence',{review_id:S.review,action:'propose',task:data.get('task'),record_id:data.get('record_id'),actor:data.get('actor'),output:{items:[item]}});S.evidenceFilter='pending';await refresh();toast('Proposal saved for human review.');});const update=()=>{const task=$('#proposal-task').value,defs=task==='extract'?e.framework.fields:e.framework.appraisal.domains;$('#proposal-key').innerHTML=defs.map(d=>`<option value="${d.id}">${pretty(d.id)}</option>`).join('');updateHint();};const updateHint=()=>{const d=e.framework.appraisal.domains.find(d=>d.id===$('#proposal-key').value);$('#judgment-hint').textContent=$('#proposal-task').value==='appraise'?'Allowed judgments: '+(d?.judgments||[]).join(', '):'No numerical effect estimates are calculated automatically.';};const sourceUpdate=()=>{$('#proposal-source').innerHTML=e.sources.filter(s=>s.record_id===$('#proposal-report').value).map(s=>`<option value="${s.id}">${esc(s.label)} (${s.pages.length} supplied pages)</option>`).join('');};$('#proposal-task').onchange=update;$('#proposal-key').onchange=updateHint;$('#proposal-report').onchange=sourceUpdate;update();sourceUpdate();}
function prepareAI(){if(!S.evidence)return toast('Start an evidence ledger first.',true);showModal('Prepare a traceable AI request.','This saves and downloads a prompt packet with the framework, criteria, source pages and a response schema. No source data is sent to a model from the dashboard.',`<div class="form-field"><label class="field-label">Task</label><select name="task"><option value="extract">Structured extraction</option><option value="appraise">Study appraisal</option><option value="gaps">Gap hypotheses · approved evidence only</option></select></div><div class="form-field"><label class="field-label">Report (not used for corpus hypotheses)</label><select name="record_id">${S.evidence.records.map(r=>`<option value="${r.id}">${esc(r.metadata.title)}</option>`).join('')}</select></div>`,'Prepare & download',async data=>{const result=await api('/api/evidence',{review_id:S.review,action:'prepare',task:data.get('task'),record_id:data.get('task')==='gaps'?null:data.get('record_id')});download(JSON.stringify(result,null,2),`evidence-request-${result.request_id}.json`,'application/json');await refresh();toast('Request packet saved and downloaded. No model call was made.');});}
function importAI(){if(!S.evidence)return toast('Start an evidence ledger first.',true);showModal('Import a model response.','Use a response envelope linked to a saved request ID and hash. Imported items are validated and remain pending human review.',`<label class="dropzone">${icon('upload')}<strong>Choose response JSON</strong><small>Provider, model, timestamp, request ID/hash and output items</small><input type="file" name="response" accept=".json" required></label>`,'Validate & import',async data=>{const value=JSON.parse(await data.get('response').text());await api('/api/evidence',{review_id:S.review,action:'import',envelope:value});S.evidenceFilter='pending';await refresh();toast('Model proposals imported. Human review is required.');});}
function paperDrawer(id){S.drawerFocus=document.activeElement;const r=S.data.records.find(r=>r.record_id===id);if(!r)return;const m=r.metadata;$('#drawer-root').innerHTML=`<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="Study details" tabindex="-1"><div class="drawer-head"><span>${r.record_id} · STUDY DETAILS</span><button class="icon-button" data-action="close-drawer" aria-label="Close study details">${icon('close')}</button></div><div class="drawer-body">${pill(status(r)[0],status(r)[1])}<h2>${esc(m.title)}</h2><p class="reading-authors">${esc(m.authors.join(', '))}</p><div class="metadata-grid"><div class="metadata-cell"><small>Publication year</small><strong>${m.year??'Unknown'}</strong></div><div class="metadata-cell"><small>Citations · ${esc(sourceName(m.source))}</small><strong>${m.citations??'Not available'}</strong></div></div><div class="drawer-section"><h3>Abstract</h3><p class="abstract">${esc(m.abstract||'No abstract was captured.')}</p></div><div class="drawer-section"><h3>Keywords</h3>${m.keywords.map(k=>`<span class="tag">${esc(k)}</span>`).join('')||'<p>No keywords were supplied.</p>'}</div><div class="drawer-section"><h3>Bibliographic identity</h3><p>${esc(m.journal)}<br>DOI: ${esc(m.doi||'Unknown')}<br>${esc(sourceName(m.source))} / ${esc(m.source_id)}</p></div><div class="drawer-section"><h3>References</h3><p>${m.references.length} supplied reference identifiers · ${m.reference_count??'Unknown'} provider-reported total</p><p style="margin-top:10px">${m.references.slice(0,10).map(esc).join('<br>')}</p></div><div class="drawer-section">${button('Open screening workspace','drawer-screening','primary','arrow')}${button('Copy citation','copy-citation','ghost','copy')}</div></div></aside>`;S.drawerRecord=id;$('.shell').inert=true;$('#sidebar').inert=true;$('.drawer').focus();}
function closeDrawer(){const wasOpen=!!$('.drawer');$('#drawer-root').innerHTML='';$('.shell').inert=false;$('#sidebar').inert=false;if(wasOpen&&S.drawerFocus?.isConnected)S.drawerFocus.focus();}
function download(value,name,type='application/json'){const blob=value instanceof Blob?value:new Blob([value],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function exportBundle(button){await busy(button,async()=>{const res=await fetch(endpoint('export'),{headers:{'X-SLR-Token':token}});if(!res.ok)throw new Error((await res.json()).error);download(await res.blob(),'litatlas-review-export.zip');toast('Review bundle downloaded with its source and decision history.');});}
function openPalette(){const p=$('#palette');p.innerHTML=`<div class="palette-header">${icon('search')}<input id="palette-input" aria-label="Search commands and studies" placeholder="Jump to a view, paper, or action…" autocomplete="off"><kbd>esc</kbd></div><div class="palette-results" id="palette-results"></div><div class="palette-footer">Search your current review · every result stays on this device</div>`;p.showModal();const draw=()=>{const q=$('#palette-input').value.toLowerCase(),views=pages.filter(x=>x[2].toLowerCase().includes(q)),papers=(S.data?.records||[]).filter(r=>[r.metadata.title,...r.metadata.authors].join(' ').toLowerCase().includes(q)).slice(0,6);$('#palette-results').innerHTML=`<div class="palette-section">GO TO</div>${views.map(([id,i,n])=>`<button class="palette-result" data-palette-go="${id}">${icon(i)}<span><strong>${n}</strong></span></button>`).join('')}${papers.length?'<div class="palette-section">STUDIES</div>':''}${papers.map(r=>`<button class="palette-result" data-palette-paper="${r.record_id}">${icon('paper')}<span><strong>${esc(r.metadata.title)}</strong><small>${r.metadata.year??'Unknown year'} · ${esc(r.metadata.authors[0]||'Unknown author')}</small></span></button>`).join('')}<div class="palette-section">ACTIONS</div><button class="palette-result" data-action="palette-new">${icon('plus')}<span><strong>Create a new review</strong></span></button>`;};$('#palette-input').oninput=draw;draw();}
function theme(){const dark=document.documentElement.dataset.theme==='dark';$('#theme-toggle').innerHTML=icon(dark?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',dark?'Use light theme':'Use dark theme');}
try{if(localStorage.getItem('litatlas-theme')==='dark')document.documentElement.dataset.theme='dark';}catch(_){}theme();
$('#theme-toggle').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('litatlas-theme',dark?'dark':'light');}catch(_){}theme();};
$('#search-trigger').onclick=openPalette;$('#profile-button').onclick=openPalette;$('#demo-new').onclick=newReview;$('#method-link').onclick=()=>go('protocol');$('#menu-button').onclick=()=>$('#sidebar').classList.toggle('open');
document.addEventListener('click',async ev=>{const t=ev.target.closest('button,a,[data-action],[data-year],[data-node]');if(!t)return;try{if(t.dataset.go){go(t.dataset.go);return;}if(t.dataset.paletteGo){$('#palette').close();go(t.dataset.paletteGo);return;}if(t.dataset.palettePaper){$('#palette').close();paperDrawer(t.dataset.palettePaper);return;}if(t.dataset.paper){paperDrawer(t.dataset.paper);return;}if(t.dataset.reviewPaper){S.selectedRecord=t.dataset.reviewPaper;const r=S.data.records.find(x=>x.record_id===S.selectedRecord);S.mode=r&&(r.title==='conflict'||r.fulltext==='conflict')?'conflicts':r?.title==='include'&&r.retrieval==='pending'?'retrieval':r?.fulltext==='include'&&!r.study_id?'link':'queue';go('screening');return;}if(t.dataset.queueRecord){S.selectedRecord=t.dataset.queueRecord;renderScreeningContent();return;}if(t.dataset.mode){S.mode=t.dataset.mode;S.selectedRecord=null;render();await loadQueue();return;}if(t.dataset.miniType){S.graphType=t.dataset.miniType;render();return;}if(t.dataset.graphType){S.graphType=t.dataset.graphType;S.selectedNode=null;S.camera={x:0,y:0,z:1};render();return;}if(t.dataset.node){if(S.page==='overview'){S.selectedNode=t.dataset.node;go('networks');}else{S.selectedNode=t.dataset.node;renderNetworkDetail();}return;}if(t.dataset.year){S.yearFilter=t.dataset.year;S.libraryPage=0;go('library');return;}if(t.dataset.evidenceFilter){S.evidenceFilter=t.dataset.evidenceFilter;S.proposal=null;renderEvidenceContent();return;}if(t.dataset.proposal){S.proposal=Number(t.dataset.proposal);renderEvidenceContent();return;}switch(t.dataset.action){case 'venue-metrics-fetch':onlineMetricsModal();break;case 'scimago-import':scimagoImportModal();break;case 'venue-metrics-import':venueMetricsModal();break;case 'corpus-export':await exportCorpus(t);break;case 'calibration-sample':{const result=await api('/api/job-calibration?id='+t.dataset.job);download(result.csv,'calibration-human-review-'+t.dataset.job+'.csv','text/csv');break;}case 'session-report':{const report=await api('/api/job-report?id='+t.dataset.job);download(report.markdown,'pipeline-session-'+t.dataset.job+'.md','text/markdown');break;}case 'retry':await boot();break;case 'new-review':newReview();break;case 'import':importModal();break;case 'search-modal':$('#modal').close();searchModal();break;case 'close-modal':$('#modal').close();break;case 'palette-new':$('#palette').close();newReview();break;case 'export':await exportBundle(t);break;case 'grid-view':S.grid=true;render();break;case 'list-view':S.grid=false;render();break;case 'prev-page':S.libraryPage=Math.max(0,S.libraryPage-1);render();break;case 'next-page':S.libraryPage++;render();break;case 'library-export':{const rows=filteredLibrary(),quote=v=>{let text=String(v??'');if(/^'*[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};download(['title,doi,year,source,authors,status',...rows.map(r=>[r.metadata.title,r.metadata.doi,r.metadata.year,r.metadata.source,r.metadata.authors.join('; '),status(r)[0]].map(quote).join(','))].join('\n'),'filtered-studies.csv','text/csv');toast(`${rows.length} filtered studies exported.`);break;}case 'close-drawer':closeDrawer();break;case 'drawer-screening':S.selectedRecord=S.drawerRecord;closeDrawer();go('screening');break;case 'copy-citation':{const m=S.data.records.find(r=>r.record_id===S.drawerRecord)?.metadata;if(m){await navigator.clipboard.writeText(`${m.authors.join(', ')} (${m.year??'n.d.'}). ${m.title}. ${m.journal}. ${m.doi}`);toast('Citation copied.');}break;}case 'include':await busy(t,()=>decide('include'));break;case 'exclude':await decide('exclude');break;case 'retrieved':await busy(t,async()=>{await api('/api/screening',{review_id:S.review,action:'retrieve',version:S.data.criteria.version,record_id:S.selectedRecord,actor:S.actor,status:'retrieved'});await refresh();toast('Full text marked as retrieved.');});break;case 'not-retrieved':showModal('Record an unretrieved report.','This remains separate from an eligibility exclusion.',area('reason','Retrieval reason','','Describe the attempt or barrier.'),'Record retrieval status',async data=>{await api('/api/screening',{review_id:S.review,action:'retrieve',version:S.data.criteria.version,record_id:S.selectedRecord,actor:S.actor,status:'not_retrieved',reason:data.get('reason')});await refresh();toast('Retrieval status saved.');});break;case 'link-study':await busy(t,async()=>{await api('/api/screening',{review_id:S.review,action:'link',version:S.data.criteria.version,record_id:S.selectedRecord,actor:S.actor,study_id:$('#study-id').value});await refresh();toast('Report linked to a study.');});break;case 'zoom-in':S.camera.z=Math.min(3.5,S.camera.z*1.2);applyCamera();break;case 'zoom-out':S.camera.z=Math.max(.4,S.camera.z/1.2);applyCamera();break;case 'zoom-reset':S.camera={x:0,y:0,z:1};applyCamera();break;case 'graph-export':if(S.graphs)download(JSON.stringify({graph:S.graphs[S.graphType],coverage:S.graphCoverage,scope:S.graphScope,layout:'exploratory grouped display; geometric distances are not similarities'},null,2),S.graphType+'-network.json');break;case 'evidence-open':go('evidence');break;case 'init-evidence':initEvidence();break;case 'add-source':sourceModal();break;case 'propose':proposeModal();break;case 'prepare-ai':prepareAI();break;case 'import-ai':importAI();break;case 'approve-evidence':await evidenceReview('approve',t);break;case 'reject-evidence':await evidenceReview('reject',t);break;case 'revise-criteria':showModal('Revise the review criteria.','A revision preserves the old decisions and returns every record to title screening. Any existing evidence ledger becomes historical.',area('text','Revised criteria',S.data.criteria.text),'Save a new criteria version',async data=>{await api('/api/screening',{review_id:S.review,action:'criteria',version:S.data.criteria.version,text:data.get('text')});S.graphs=null;await refresh();toast('New criteria version saved. Screening starts a new pass.');});break;}}catch(err){toast(err.message,true);}});
document.addEventListener('keydown',ev=>{if(ev.key==='Tab'&&$('.drawer')){const items=$$('button,a,input,select,textarea,[tabindex="0"]',$('.drawer'));if(items.length){if(ev.shiftKey&&document.activeElement===items[0]){ev.preventDefault();items.at(-1).focus();}else if(!ev.shiftKey&&document.activeElement===items.at(-1)){ev.preventDefault();items[0].focus();}}}if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();openPalette();return;}if(ev.key==='Escape'){closeDrawer();$('#sidebar').classList.remove('open');}if(ev.target.matches('input,textarea,select')||$('#modal').open||$('#palette').open)return;if(ev.key==='Enter'&&ev.target.dataset.node){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(S.page==='screening'&&S.mode==='queue'&&['i','e'].includes(ev.key.toLowerCase())){ev.preventDefault();const action=ev.key.toLowerCase()==='i'?'include':'exclude';$(`[data-action="${action}"]`)?.click();}});
window.addEventListener('hashchange',()=>route().catch(err=>toast(err.message,true)));
boot();

function analyticsNumber(value){return value===null||value===undefined?'—':Number(value).toLocaleString();}
function renderAnalytics(){const d=S.analyticsData,years=d?.metric_years||[],categories=d?.metric_categories||[];return heading('Your corpus, measured clearly.','A publication-level summary, metadata coverage, and ranked venues with dated external metrics.',button('Fetch online','venue-metrics-fetch','soft','search')+button('Import SCImago','scimago-import','soft','upload')+button('Import venue metrics','venue-metrics-import','soft','upload')+button('Export analysis','corpus-export','','download'))+reviewStrip()+`<div class="toolbar corpus-analysis-controls"><div class="toolbar-group"><label class="field-label" for="analysis-scope">Corpus</label><select id="analysis-scope" class="filter-select"><option value="all" ${S.analysisScope==='all'?'selected':''}>All captured reports</option><option value="included" ${S.analysisScope==='included'?'selected':''}>Included reports only</option></select><label class="field-label" for="metric-year">Metric year</label><select id="metric-year" class="filter-select" ${years.length?'':'disabled'}>${years.length?years.map(y=>`<option value="${y}" ${Number(S.metricYear||d.metric_year)===y?'selected':''}>${y}</option>`).join(''):'<option>No external snapshot</option>'}</select><label class="field-label" for="metric-category">Category</label><select id="metric-category" class="filter-select" ${categories.length?'':'disabled'}><option value="">All categories</option>${categories.map(c=>`<option value="${esc(c)}" ${S.metricCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div></div><div id="analytics-content">${d?analyticsContent(d):'<div class="loading-state"><span class="spinner"></span><p>Calculating the selected corpus…</p></div>'}</div>`;}
function analyticsContent(d){const definitions=[['papers','Papers','Retained reports in this scope'],['authors','Authors (observed)','Identifiers or unresolved normalized names'],['sources','Publication venues','Journals, proceedings and repositories'],['affiliations','Affiliations (observed)','Institution identifiers or reported names'],['keywords','Unique keywords',`${analyticsNumber(d.keyword_occurrences)} per-report keyword occurrences`],['subject_areas','Subject areas','Distinct labels within each taxonomy'],['citations','Citations (reported)','Sum of available retained-record counts'],['countries','Affiliation countries','Reported country labels / codes']];const cards=definitions.map(([key,label,note])=>`<article class="metric"><div class="metric-label">${label}</div><div class="metric-value">${analyticsNumber(d.totals[key])}</div><div class="corpus-stat-note">${esc(note)}</div>${d.coverage[key]?`<div class="corpus-coverage">Metadata on ${d.coverage[key].records.toLocaleString()} / ${d.coverage[key].total.toLocaleString()} reports</div>`:'<div class="corpus-coverage">Report-level count; not distinct studies</div>'}</article>`).join('');return `<section class="metrics corpus-metrics" aria-label="Summary of results">${cards}</section><div class="notice">${icon('paper')}<span>${d.scope==='included'?(d.screening_complete?'Included-report subset':'Included-report subset (provisional; screening incomplete)'):'Captured corpus'} · these totals describe available metadata. — means unavailable; zero is shown only for a known zero or an empty corpus. Author and institution names are not disambiguated.</span></div><section class="card corpus-venue-card"><div class="card-head"><div><h2>Top publication venues</h2><p class="card-subtitle">Ranked by TP: publications in the selected corpus. External metrics remain independent of corpus counts.</p></div></div><div class="toolbar corpus-table-toolbar"><input id="venue-search" class="search-input" aria-label="Find publication venue" placeholder="Find a venue, publisher or ISSN…" value="${esc(S.venueSearch)}"><select id="venue-limit" class="filter-select" aria-label="Number of venues">${[10,25,100].map(n=>`<option value="${n}" ${S.venueLimit===n?'selected':''}>Top ${n}</option>`).join('')}</select></div><div id="venue-table-content">${venueTable(d)}</div><div class="card-body"><p class="detail-caption">TP = corpus publications. CiteScore, SNIP, SJR, quartile and source H-index use dated provider snapshots. Source H-index is the provider-reported venue measure, not this corpus’s H-index. * = explicitly not applicable; — = not supplied. Quartiles are category-specific.</p>${d.metric_import?`<p class="detail-caption">Snapshot: ${esc(d.metric_import.filename)} · imported ${esc(d.metric_import.imported_utc)} · metric year ${d.metric_year}. ${d.unmatched_metric_rows} selected snapshot rows remain unmatched. Ambiguous matches are not filled automatically.</p>`:'<p class="detail-caption">No external metrics saved. Import a free SCImago CSV for SJR, quartiles and H-index, or use Fetch online with configured provider access. CiteScore and SNIP need a separate source.</p>'}<p class="detail-caption">Exports include every venue in the selected corpus, independently of this table’s search and display limit. ${d.missing_venue_records} reports have no venue metadata.</p>${metricFootnotes(d)}</div></section><details class="card corpus-methods"><summary>Definitions, coverage and citation providers</summary><div class="card-body">${d.notices.map(n=>`<p class="detail-caption">${esc(n)}</p>`).join('')}${d.subject_taxonomies.map(t=>`<p class="detail-caption">${esc(t.taxonomy)}: ${t.areas} distinct subject labels.</p>`).join('')}${d.citations_by_provider.map(c=>`<p class="detail-caption">${esc(c.source)}: ${analyticsNumber(c.citation_sum_known)} reported citations; counts available for ${c.records_with_citations}/${c.records} reports.</p>`).join('')}</div></details>`;}
function venueTable(d){const query=S.venueSearch.toLocaleLowerCase(),rows=d.venues.filter(v=>[v.name,v.publisher,...v.issns].join(' ').toLocaleLowerCase().includes(query)),visible=rows.slice(0,S.venueLimit);const value=(m,key)=>m?.statuses?.[key]==='not-applicable'?'*':m?.[key]===null||m?.[key]===undefined?'—':esc(m[key]);return visible.length?`<div class="corpus-table-wrap"><table class="corpus-venue-table"><thead><tr>${['#','Publication venue','TP','CiteScore','SNIP','SJR','Quartile','Publisher','Source H-index','Year / category','Metric provenance'].map(c=>`<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${visible.map(v=>{const m=v.external_metrics;return `<tr><td>${v.rank}</td><td><strong>${esc(v.name)}</strong><small>${esc(v.issns.join('; '))}</small>${v.metric_match==='ambiguous'?'<small>Ambiguous metric rows — choose a category</small>':''}</td><td>${v.publications.toLocaleString()}</td><td>${value(m,'citescore')}</td><td>${value(m,'snip')}</td><td>${value(m,'sjr')}</td><td>${m?.quartile?esc(m.quartile):'—'}${m?.quartile?`<small>${esc(m.quartile_basis||'Basis unspecified')}</small>`:''}</td><td>${esc(v.publisher||'—')}</td><td>${value(m,'h_index')}</td><td>${m?`${m.year}<small>${esc(m.category||'Category not supplied')}</small>`:'—'}</td><td>${m?`${esc(m.metric_source)} <sup>[${metricSources(d).indexOf(metricCitation(m))+1}]</sup><small>Retrieved ${esc(m.retrieved_date)}</small><small>Matched by ${esc(v.metric_match)}</small>`:'—'}</td></tr>`;}).join('')}</tbody></table></div><div class="card-bottom"><span>Showing ${visible.length} of ${rows.length} matching venues · ${d.venues.length} in this corpus</span></div>`:empty('No reported venues in this view','Choose another corpus scope or search term. Missing venue metadata is not counted as an additional venue.',null,null,'book');}
let analyticsRequest=0;
async function loadAnalytics(){const id=S.review,request=++analyticsRequest;const data=await api(endpoint('corpus',{scope:S.analysisScope,...(S.metricYear?{year:S.metricYear}:{}),...(S.metricCategory?{category:S.metricCategory}:{})}));if(id!==S.review||request!==analyticsRequest||S.page!=='analytics')return;S.analyticsData=data;render();}
function venueMetricsModal(){showModal('Add a dated venue-metrics snapshot.','Upload a CSV you are authorized to use. Columns: venue_id, issn or journal; year; metric_source; retrieved_date; and optional citescore, snip, sjr, quartile, category, publisher, h_index, source_url, quartile_basis. A quartile requires its category. Blank means missing; * means not applicable.',`<label class="dropzone">${icon('upload')}<strong>Choose a venue-metrics CSV</strong><small>Up to 5 MB · dated external snapshot</small><input type="file" name="metrics" accept=".csv" required></label>`,'Import metric snapshot',async data=>{const file=data.get('metrics');if(!file?.size||file.size>5*1024*1024)throw new Error('Choose a nonempty CSV up to 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.slice(i,i+8192));const result=await api('/api/venue-metrics',{review_id:S.review,name:file.name,base64:btoa(binary)});S.analyticsData=null;S.metricYear='';S.metricCategory='';await refresh();toast(`${result.rows} external metric rows saved with provenance.`);});}
async function exportCorpus(button){await busy(button,async()=>{const response=await fetch(endpoint('corpus-export',{scope:S.analysisScope,...(S.metricYear?{year:S.metricYear}:{}),...(S.metricCategory?{category:S.metricCategory}:{})}),{headers:{'X-SLR-Token':token}});if(!response.ok)throw new Error((await response.json()).error||'Analysis export failed.');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='corpus-analysis.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);});}

function metricCitation(m){return JSON.stringify([m.metric_source,m.year,m.retrieved_date,m.source_url||'',m.quartile_basis||'',m.category||'']);}
function metricSources(d){return [...new Set(d.venues.filter(v=>v.external_metrics).map(v=>metricCitation(v.external_metrics)))];}
function metricFootnotes(d){const refs=metricSources(d);return refs.length?`<h3>Metric sources</h3><ol>${refs.map(ref=>{const [source,year,retrieved,url,basis,category]=JSON.parse(ref);return `<li class="detail-caption">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(source)}</a>`:esc(source)}. Metric year ${year}; retrieved ${esc(retrieved)}.${basis?` Quartile: ${esc(basis)}; ${esc(category)}.`:''}</li>`;}).join('')}</ol><p class="detail-caption">SCImago best quartile means the highest quartile across its reported categories. It is separate from JCR JIF quartiles. Journal H-index is a captured provider value, not an annual corpus measure.</p>`:'';}
function onlineMetricsModal(){showModal('Retrieve journal metrics online.','Uses official provider APIs and server-side keys. Elsevier supplies CiteScore, SNIP and SJR; Clarivate supplies category-specific JCR JIF quartiles. Only the exact requested year and verified ISSNs are accepted. A successful lookup replaces the active metrics snapshot; previous snapshots stay on disk. Use SCImago import for the free download route.',`<label class="field-label">Provider<select class="filter-select" name="provider"><option value="elsevier">Elsevier Scopus (ELSEVIER_API_KEY)</option><option value="clarivate">Clarivate JCR (CLARIVATE_API_KEY)</option></select></label><label class="field-label">Metric year<input class="search-input" name="year" type="number" min="1997" max="${new Date().getFullYear()}" value="${new Date().getFullYear()-1}" required></label><label class="field-label">Top venues to look up<input class="search-input" name="limit" type="number" min="1" max="100" value="10" required></label>`,'Start lookup',async data=>{await api('/api/venue-metrics-fetch',{review_id:S.review,provider:data.get('provider'),year:Number(data.get('year')),limit:Number(data.get('limit')),scope:S.analysisScope});S.metricYear='';S.metricCategory='';S.analyticsData=null;await refresh();toast('Journal metric lookup started. Results and errors are recorded in the session log.');});}
function scimagoImportModal(){showModal('Import a free SCImago download.','Open <a href="https://www.scimagojr.com/journalrank.php" target="_blank" rel="noopener noreferrer">SCImago Journal Rankings</a>, select the metric year and use Download data. Upload the semicolon-delimited CSV here. Choose the year used for that download; the CSV does not reliably identify its year. This replaces the active snapshot and preserves the original file. CiteScore and SNIP remain blank.',`<label class="field-label">Selected SCImago metric year<input name="year" class="search-input" type="number" min="1997" max="${new Date().getFullYear()}" required></label><label class="field-label">Date downloaded<input name="retrieved" class="search-input" type="date" required></label><label class="dropzone"><strong>Choose SCImago Download data CSV</strong><small>Up to 5 MB; filter the download if needed</small><input name="metrics" type="file" accept=".csv" required></label>`,'Import SCImago data',async data=>{const file=data.get('metrics');if(!file?.size||file.size>5*1024*1024)throw new Error('Choose a nonempty CSV up to 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.slice(i,i+8192));await api('/api/venue-metrics',{review_id:S.review,name:file.name,base64:btoa(binary),format:'scimago',year:Number(data.get('year')),retrieved_date:data.get('retrieved')});S.metricYear='';S.metricCategory='';S.analyticsData=null;await refresh();toast('SCImago metrics imported with source footnotes.');});}
